// HasAssignedUser applies the HasEdge predicate on the "assigned_user" edge.
func HasAssignedUser() predicate.SocialAccount {
	return predicate.SocialAccount(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AssignedUserTable, AssignedUserColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAssignedUserWith applies the HasEdge predicate on the "assigned_user" edge with a given conditions (other predicates).
func HasAssignedUserWith(preds ...predicate.User) predicate.SocialAccount {
	return predicate.SocialAccount(func(s *sql.Selector) {
		step := newAssignedUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

